(function(root){
 'use strict';
 const MAX_ROUNDS=240;
 const measured=x=>Number.isFinite(x)&&x>=0?x:null;
 const num=x=>Number.isFinite(x)&&x>=0?x:0;
 function fresh(){return {rounds:[],totals:{vapor:0,liquid:0,credits:0,count:0,energy:0,knownEnergy:0,knownLiquid:0},archived:0};}
 function load(raw){const h=fresh();let last=0;for(const p of Array.isArray(raw?.rounds)?raw.rounds.slice(-MAX_ROUNDS):[]){if(!Number.isInteger(p.number)||p.number<=last)continue;last=p.number;h.rounds.push({number:p.number,vapor:num(p.vapor),smoke:measured(p.smoke),largest:measured(p.largest),longest:measured(p.longest),session:measured(p.session),firing:measured(p.firing),throughputBonus:measured(p.throughputBonus),energy:Number.isFinite(p.energy)&&p.energy>=0?p.energy:null,cumulativeEnergy:num(p.cumulativeEnergy),liquid:Number.isFinite(p.liquid)&&p.liquid>=0?p.liquid:null,credits:Number.isFinite(p.credits)&&p.credits>=0?p.credits:null,cumulativeVapor:num(p.cumulativeVapor),cumulativeLiquid:num(p.cumulativeLiquid),cumulativeCredits:num(p.cumulativeCredits)});}for(const k in h.totals)h.totals[k]=num(raw?.totals?.[k]);const p=h.rounds.at(-1);if(p){h.totals.energy=Math.max(h.totals.energy,p.cumulativeEnergy);h.totals.vapor=Math.max(h.totals.vapor,p.cumulativeVapor);h.totals.liquid=Math.max(h.totals.liquid,p.cumulativeLiquid);h.totals.credits=Math.max(h.totals.credits,p.cumulativeCredits);h.totals.count=Math.max(h.totals.count,h.rounds.length);}h.archived=Math.max(0,h.totals.count-h.rounds.length);return h;}
 function append(h,r){if(!r||!Number.isInteger(r.number)||r.number<=0)return false;const extra={session:r.timingKnown===true?measured(r.elapsed):null,firing:r.firingKnown===true?measured(r.firingTime):null,throughputBonus:r.earnings?.version>=3?measured(r.earnings.throughputBonus):null,smoke:measured(r.smoke),largest:r.largestKnown===true?measured(r.largestEligible):null,longest:r.durationKnown===true?measured(r.longestClean):null};const existing=h.rounds.find(p=>p.number===r.number);if(existing){for(const k in extra)if(existing[k]==null&&extra[k]!==null)existing[k]=extra[k];return false;}if(r.number<=(h.rounds.at(-1)?.number||0))return false;const energy=r.energyKnown===true?num(r.energyUsed):null,liquid=r.liquidKnown===true?num(r.liquidUsed):null,credits=r.scoreModel==='credits'?num(r.score):null;if(energy!==null){h.totals.energy+=energy;h.totals.knownEnergy++;}h.totals.vapor+=num(r.vapor);if(liquid!==null){h.totals.liquid+=liquid;h.totals.knownLiquid++;}if(credits!==null)h.totals.credits+=credits;h.totals.count++;h.rounds.push({number:r.number,vapor:num(r.vapor),...extra,energy,cumulativeEnergy:h.totals.energy,liquid,credits,cumulativeVapor:h.totals.vapor,cumulativeLiquid:h.totals.liquid,cumulativeCredits:h.totals.credits});if(h.rounds.length>MAX_ROUNDS)h.rounds.splice(0,h.rounds.length-MAX_ROUNDS);h.archived=h.totals.count-h.rounds.length;return true;}
 function metricSeries(h,key,cumulative=false){let numerator=0,denominator=0,count=0;const values=h.rounds.map(p=>{let a=null,b=null;if(key==='session'||key==='firing'){a=measured(p[key]);b=1;}else if(key==='throughput'){a=measured(p.vapor);b=measured(p.session);if(a!==null)a/=1000;}else if(key==='liquidRate'){a=measured(p.liquid);b=measured(p.session);}else if(key==='averagePower'){a=measured(p.energy);b=measured(p.firing);if(a!==null)a*=3600;}else if(key==='throughputBonus')return measured(p.throughputBonus);if(a===null||b===null||b<=0)return null;count++;numerator+=a;denominator+=b;return cumulative?(key==='session'||key==='firing'?numerator:numerator/denominator):a/b;});return {values,count,total:h.rounds.length};}
 const api={metricSeries,MAX_ROUNDS,fresh,load,append};root.CloudHistory=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
